// Resolve the caller's role and normalize the body.
const who = $('Article Whoami').first().json || {};
const userId = who.user_id ? String(who.user_id).trim() : null;
const FOUNDER = '@collective_boundary730383:hyphae.social';
let roles = {};
try {
  const raw = $('Article Fetch Roles').first().json || {};
  const text = typeof raw.data === 'string' ? raw.data : JSON.stringify(raw);
  const parsed = JSON.parse(text);
  const lay = (parsed && parsed.layout) || parsed;
  if (lay && lay.roles && typeof lay.roles === 'object') roles = lay.roles;
} catch (e) {}
const role = userId === FOUNDER ? 'admin' : (userId ? (roles[userId] || null) : null);
const authorized = !!userId && (role === 'admin' || role === 'editor');

const hook = $('Article Webhook').first().json;
const body = hook.body && typeof hook.body === 'object' ? hook.body : hook;
const slug = (String(body.slug || '').replace(/[^a-z0-9-]/gi, '-').replace(/^-+|-+$/g, '').slice(0, 80)).toLowerCase();
const line = body.line != null ? String(body.line).replace(/\r?\n/g, ' ').trim() : '';
const valid = !!(slug && line);
const identifier = ('npj-article-' + slug).slice(0, 90);
const filename = slug + '.jsonl';
return [{ json: {
  authorized, valid, user_id: userId, role, slug, line, identifier, filename, isAdmin: role === 'admin',
  downloadUrl: 'https://archive.org/download/' + identifier + '/' + filename,
  error: !authorized ? 'unauthorized' : (!valid ? 'missing slug or line' : null)
} }];

// Read-modify-append: existing log + the new line. Enforce the per-article
// assignee gate (admin always; editor only if the article is new or lists them).
function djb2(line){ let h=5381; for(let i=0;i<line.length;i++) h=((h<<5)+h+line.charCodeAt(i))>>>0; return ('0000000'+h.toString(16)).slice(-7); }
const meta = $('Article Authorize').first().json || {};
const resp = $input.first().json || {};
let existing = '';
if (resp && typeof resp.data === 'string') existing = resp.data;
else if (typeof resp.body === 'string') existing = resp.body;
else if (typeof resp === 'string') existing = resp;
// a 404/HTML error page is not a log — treat anything that isn't NDJSON-ish as empty
if (existing && existing.trim()[0] !== '{') existing = '';

// assignee gate for a non-admin editor on an EXISTING article
if (!meta.isAdmin && existing) {
  let assignees = [];
  try { const genesis = JSON.parse(existing.split('\n').find(l => l.trim()) || '{}'); const op = genesis.operand || {}; assignees = Array.isArray(op.assignees) ? op.assignees : []; } catch (e) {}
  if (assignees.indexOf(meta.user_id) < 0) return [{ json: { __forbidden: true, user_id: meta.user_id, role: meta.role, slug: meta.slug, error: 'not an assignee on this article' } }];
}

const prev = existing ? (existing.endsWith('\n') ? existing : existing + '\n') : '';
const finalText = prev + meta.line + '\n';
return [{ json: {
  __forbidden: false, identifier: meta.identifier, filename: meta.filename,
  user_id: meta.user_id, role: meta.role, bytes: finalText.length, base_sha: djb2(meta.line)
}, binary: { data: { data: Buffer.from(finalText, 'utf8').toString('base64'), mimeType: 'application/x-ndjson', fileName: meta.filename } } }];

const r = $input.first().json || {};
const built = $('Article Build').first().json || {};
const status = Number(r.statusCode || 0) || null;
const ok = !r.error && (!status || status < 400);
const url = ok ? ('https://archive.org/download/' + built.identifier + '/' + built.filename) : null;
return [{ json: {
  ok, statusCode: ok ? 200 : (status || 502), url,
  identifier: built.identifier, filename: built.filename, bytes: built.bytes, base_sha: built.base_sha,
  user: built.user_id, role: built.role,
  error: ok ? null : ((typeof r.error === 'string' ? r.error : (r.error && r.error.message)) || ('archive.org PUT failed (' + (status || '?') + ')'))
} }];
